"""Review finer joint reference fields and restored source provenance."""
from pathlib import Path
import os,sys,json,csv,hashlib
P=Path(__file__).resolve().parent;sys.path.insert(0,str(P/'solver-libraries'));os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np
O=P/'engineering-v24-results';cases=[];comparisons=[];integrity=[]
for size in ['child_large','adult_small']:
 for side in ['outward','inward']:
  f=O/f'{size}_h1.5_{side}.json';r=json.loads(f.read_text());assert r['converged'];assert hashlib.sha256(f.with_suffix('.npz').read_bytes()).hexdigest()==r['raw_sha256']
  r['numerical_controls_pass']=r['independent_residual']<1e-7 and r['force_balance_N']<1e-6 and r['moment_balance_Nmm']<1e-5 and r['coulomb_excess_MPa']<1e-10 and min(r['contact_derivative_errors'])<1e-3 and all(x['passed'] for x in r['rigid_motion_controls']);cases.append(r)
  old=json.loads((P/'engineering-v23-results'/f'{size}_h1.9_{side}.json').read_text());assert old['source_CAD_sha256']==r['source_CAD_sha256']
  for a,b in zip(old['stress'],r['stress']):
   for method in ['interior125','boundary35']:
    coarse=a['sampled_peaks_MPa'][method];fine=b['sampled_peaks_MPa'][method];delta=abs(fine/coarse-1)*100;comparisons.append(dict(size=size,direction=side,component=a['component'],sampling=method,old_mesh_mm=1.9,new_mesh_mm=1.5,old_sampled_peak_MPa=coarse,new_sampled_peak_MPa=fine,change_percent=delta,chosen_5_percent_pass=delta<5))
for f in (P/'engineering-v23-results').glob('*h*.json'):
 r=json.loads(f.read_text());raw=f.with_suffix('.npz');actual=hashlib.sha256(raw.read_bytes()).hexdigest();assert actual==r['raw_sha256'];integrity.append(dict(path=raw.relative_to(P).as_posix(),sha256=actual))
audit=json.loads((O/'relocation_source_audit.json').read_text());assert audit['verified']==audit['unique_sources'] and not audit['unresolved'];controls=json.loads((O/'path_loader_controls.json').read_text());assert controls['all_pass'];recovery=json.loads((O/'historical_source_recovery.json').read_text());unique={r['sha256']:r for r in recovery['exact_recoveries']};assert len(unique)==4
summary=dict(date='2026-10-24',revision='V24',finer_campaign_complete=True,new_equilibrium_fields=len(cases),all_numerical_controls_pass=all(r['numerical_controls_pass'] for r in cases),stress_comparisons=len(comparisons),stress_comparison_passes=sum(x['chosen_5_percent_pass'] for x in comparisons),whole_part_strength_demonstrated=False,all_product_software_testing_complete=False,CAD_shapes_changed=False,physical_tests=0,cases=cases,comparisons=comparisons,verified_recorded_CAD_references=audit['references'],distinct_recorded_CAD_paths_and_hashes=audit['unique_sources'],recovered_historical_sources=list(unique.values()),earlier_V23_raw_fields_unchanged=integrity,scope='Same isolated V19 CAD and corrected virtual spacer equations, new global 1.5 mm meshes. Fixed E3500 MPa nu0.35 preload140 N friction0.2 +/-2 N side force. Nearest-node warm interpolation is initialization only; final equilibrium gates still required. No strength or whole-product qualification.')
assert summary['all_numerical_controls_pass']
(O/'review_status.json').write_text(json.dumps(summary,indent=2))
with (O/'stress_comparisons.csv').open('w',newline='') as f:
 writer=csv.DictWriter(f,fieldnames=list(comparisons[0]));writer.writeheader();writer.writerows(comparisons)
rows=[['Joint reference solve','Completed','Four finer fields meet numerical checks','Fixed model assumptions only'],['Refined stress reliability','Completed with failures retained',str(summary['stress_comparison_passes'])+' of 16 pairwise comparisons pass','Real edge spacer fastener and load design still needed'],['Project source resolution','Completed for primary loaders','304 recorded path/hash pairs verified and seven loader controls','Other historical scripts not all migrated'],['Historical CAD provenance','Four exact old versions restored','Archive members match saved SHA256 hashes','Historical current-root files kept unchanged'],['CAD folding and adjustment','Earlier finite checks only','V19 shapes and V21 motion/packing records','No continuous motion or pinch qualification'],['Full cushion/head contact','Input and model gated','Reduced foam screens retained','Need grade curves cover seams friction and worn geometry'],['Sony mounting','Dimension gated','Public pad envelope only','Need exact skirt groove carrier and tolerances'],['Sound heat creep fatigue drop cleaning','Input and design gated','No calibrated whole-product validation','Need material/assembly data and completed design'],['Comfort and sensory acceptance','Requires people','No wearer test','Cannot be validated by software'],['Complete product software sign off','Not achieved','No product readiness claim','Failed and missing requirements remain open']]
with (O/'remaining_test_register.csv').open('w',newline='') as f:
 writer=csv.writer(f);writer.writerow(['Area','Status','Evidence','Limit']);writer.writerows(rows)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig,ax=plt.subplots(figsize=(9,4.3));labels=[];inside=[];boundary=[]
for size in ['child_large','adult_small']:
 for side in ['outward','inward']:
  for comp in ['tongue','fork']:
   labels.append(('Child' if size=='child_large' else 'Adult')+'\n'+side+'\n'+comp)
   for method,values in [('interior125',inside),('boundary35',boundary)]:values.append(next(r['change_percent'] for r in comparisons if r['size']==size and r['direction']==side and r['component']==comp and r['sampling']==method))
x=np.arange(8);ax.bar(x-.18,inside,.36,label='125 interior samples');ax.bar(x+.18,boundary,.36,label='35 samples including boundaries');ax.axhline(5,color='firebrick',ls='--',label='Chosen 5 percent check');ax.set_xticks(x,labels,fontsize=8);ax.set_ylabel('Peak change between meshes percent');ax.legend(loc='lower center',bbox_to_anchor=(.5,1.01),ncol=3,fontsize=8);ax.set_title('New 1.5 mm mesh compared with the 1.9 mm mesh',pad=35);fig.tight_layout();fig.savefig(P/'documents/images/V24_finer_comparison.png',dpi=160);plt.close(fig)
text=f'''# V24 finer reference mesh and source recovery\n\nFour new corrected reference fields use a global 1.5 mm target, following V23 at 1.9 mm. All numerical controls pass. Of 16 fixed 5 percent peak comparisons, {summary['stress_comparison_passes']} pass. Read stress_comparisons.csv; no failed comparison is deleted or replaced by a mean stress. The 125 point interior and 35 point boundary lattice are finite samples. This does not bound a global peak or qualify strength. Same CAD and assumed continuum parameters, not a new material or headset design.\n\nThe primary geometry loaders now resolve relocated CAD by its recorded SHA256. The source audit covers 623 recorded references and 304 distinct path/hash pairs. Four old V12 versions were recovered exactly from existing ZIP members into source-archive, without replacing newer root files or editing old recorded paths. Seven loader controls passed, including rejection of a wrong hash. Other historical scripts were not all migrated.\n\nRun v24_finer_campaign.py then v24_review.py with the saved numerical dependencies. The model warm-starts by nearest-node mapping but requires the same final force residual and contact controls. The first execution attempt failed while comparing differently sized load vectors; its log is retained. The corrected check compares resultant loads; the prescribed load equation is unchanged. Source resolution checks use v24_path_audit.py and v24_path_controls.py. All original V23 raw fields remain unchanged.\n\nThe current finer campaign is complete, but whole-product software sign off is not achieved. Detailed physical contact and edge design, material curves, cover and head geometry, exact Sony mounting and acoustic/thermal/durability inputs remain required. Wearer acceptance needs people. No device has been physically tested and no product benefit or manufacturing release is claimed.\n'''
(O/'README.md').write_text(text);print(json.dumps({k:v for k,v in summary.items() if k not in ['cases','comparisons','recovered_historical_sources','earlier_V23_raw_fields_unchanged']},indent=2))
